    MedicalScribeChannelDefinition.add_member(:participant_role, Smithy::Schema::Shapes::ShapeRef.new(shape: MedicalScribeParticipantRole, location_name: 'ParticipantRole', traits: {"smithy.api#documentation" => "<p>Specify the participant that you want to flag.\n      The allowed options are <code>CLINICIAN</code> and\n      <code>PATIENT</code>.\n    </p>", "smithy.api#required" => {}}))
    MedicalScribeChannelDefinition.type = Types::MedicalScribeChannelDefinition
