    MedicalScribeConfigurationEvent.add_member(:vocabulary_filter_name, Smithy::Schema::Shapes::ShapeRef.new(shape: VocabularyFilterName, location_name: 'VocabularyFilterName', traits: {"smithy.api#documentation" => "<p>Specify the name of the custom vocabulary filter you want to include in your streaming session.\n      Custom vocabulary filter names are case-sensitive.\n    </p>\n         <p>If you include <code>VocabularyFilterName</code> in the <code>MedicalScribeConfigurationEvent</code>,\n      you must also include <code>VocabularyFilterMethod</code>.\n    </p>"}))
    MedicalScribeConfigurationEvent.add_member(:vocabulary_filter_method, Smithy::Schema::Shapes::ShapeRef.new(shape: MedicalScribeVocabularyFilterMethod, location_name: 'VocabularyFilterMethod', traits: {"smithy.api#documentation" => "<p>Specify how you want your custom vocabulary filter applied to the streaming session.</p>\n         <p>To replace words with <code>***</code>, specify <code>mask</code>.\n    </p>\n         <p>To delete words, specify <code>remove</code>.\n    </p>\n         <p>To flag words without changing them, specify <code>tag</code>.\n    </p>"}))
    MedicalScribeConfigurationEvent.add_member(:resource_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: IamRoleArn, location_name: 'ResourceAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of an IAM role that has permissions to access the Amazon S3 output\n      bucket you specified, and use your KMS key if supplied. If the role that you specify doesn’t have the\n      appropriate permissions, your request fails. </p>\n         <p>\n      IAM\n      role ARNs have the format\n      <code>arn:partition:iam::account:role/role-name-with-path</code>.\n      For example: <code>arn:aws:iam::111122223333:role/Admin</code>.\n    </p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/health-scribe-streaming.html\">Amazon Web Services HealthScribe</a>.</p>", "smithy.api#required" => {}}))
