    StartCallAnalyticsStreamTranscriptionRequest.add_member(:language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: CallAnalyticsLanguageCode, location_name: 'LanguageCode', traits: {"smithy.api#documentation" => "<p>Specify the language code that represents the language spoken in your audio.</p>\n         <p>For a list of languages supported with real-time Call Analytics, refer to the \n      <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/supported-languages.html\">Supported \n        languages</a> table.</p>", "smithy.api#httpHeader" => "x-amzn-transcribe-language-code", "smithy.api#required" => {}}))
    StartCallAnalyticsStreamTranscriptionRequest.add_member(:media_sample_rate_hertz, Smithy::Schema::Shapes::ShapeRef.new(shape: MediaSampleRateHertz, location_name: 'MediaSampleRateHertz', traits: {"smithy.api#documentation" => "<p>The sample rate of the input audio (in hertz). Low-quality audio, such as telephone audio,\n      is typically around 8,000 Hz. High-quality audio typically ranges from 16,000 Hz to 48,000 Hz.\n      Note that the sample rate you specify must match that of your audio.</p>", "smithy.api#httpHeader" => "x-amzn-transcribe-sample-rate", "smithy.api#required" => {}}))
    StartCallAnalyticsStreamTranscriptionRequest.add_member(:media_encoding, Smithy::Schema::Shapes::ShapeRef.new(shape: MediaEncoding, location_name: 'MediaEncoding', traits: {"smithy.api#documentation" => "<p>Specify the encoding of your input audio. Supported formats are:</p>\n         <ul>\n            <li>\n               <p>FLAC</p>\n            </li>\n            <li>\n               <p>OPUS-encoded audio in an Ogg container</p>\n            </li>\n            <li>\n               <p>PCM (only signed 16-bit little-endian audio formats, which does not include WAV)</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/how-input.html#how-input-audio\">Media formats</a>.</p>", "smithy.api#httpHeader" => "x-amzn-transcribe-media-encoding", "smithy.api#required" => {}}))
    StartCallAnalyticsStreamTranscriptionRequest.add_member(:vocabulary_name, Smithy::Schema::Shapes::ShapeRef.new(shape: VocabularyName, location_name: 'VocabularyName', traits: {"smithy.api#documentation" => "<p>Specify the name of the custom vocabulary that you want to use when processing your\n      transcription. Note that vocabulary names are case sensitive.</p>\n         <p>If the language of the specified custom vocabulary doesn't match the language identified in\n      your media, the custom vocabulary is not applied to your transcription.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/custom-vocabulary.html\">Custom vocabularies</a>.</p>", "smithy.api#httpHeader" => "x-amzn-transcribe-vocabulary-name"}))
    StartCallAnalyticsStreamTranscriptionRequest.add_member(:session_id, Smithy::Schema::Shapes::ShapeRef.new(shape: SessionId, location_name: 'SessionId', traits: {"smithy.api#documentation" => "<p>Specify a name for your Call Analytics transcription session. If you don't include this parameter\n      in your request, Amazon Transcribe generates an ID and returns it in the response.</p>", "smithy.api#httpHeader" => "x-amzn-transcribe-session-id"}))
    StartCallAnalyticsStreamTranscriptionRequest.add_member(:audio_stream, Smithy::Schema::Shapes::ShapeRef.new(shape: AudioStream, location_name: 'AudioStream', traits: {"smithy.api#documentation" => "<p>An encoded stream of audio blobs. Audio streams are encoded as either HTTP/2 or WebSocket \n      data frames.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/streaming.html\">Transcribing streaming audio</a>.</p>", "smithy.api#httpPayload" => {}, "smithy.api#required" => {}}))
    StartCallAnalyticsStreamTranscriptionRequest.add_member(:vocabulary_filter_name, Smithy::Schema::Shapes::ShapeRef.new(shape: VocabularyFilterName, location_name: 'VocabularyFilterName', traits: {"smithy.api#documentation" => "<p>Specify the name of the custom vocabulary filter that you want to use when processing your\n      transcription. Note that vocabulary filter names are case sensitive.</p>\n         <p>If the language of the specified custom vocabulary filter doesn't match the language identified in\n      your media, the vocabulary filter is not applied to your transcription.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/vocabulary-filtering.html\">Using vocabulary filtering with unwanted \n      words</a>.</p>", "smithy.api#httpHeader" => "x-amzn-transcribe-vocabulary-filter-name"}))
    StartCallAnalyticsStreamTranscriptionRequest.add_member(:vocabulary_filter_method, Smithy::Schema::Shapes::ShapeRef.new(shape: VocabularyFilterMethod, location_name: 'VocabularyFilterMethod', traits: {"smithy.api#documentation" => "<p>Specify how you want your vocabulary filter applied to your transcript.</p>\n         <p>To replace words with <code>***</code>, choose <code>mask</code>.</p>\n         <p>To delete words, choose <code>remove</code>.</p>\n         <p>To flag words without changing them, choose <code>tag</code>.</p>", "smithy.api#httpHeader" => "x-amzn-transcribe-vocabulary-filter-method"}))
    StartCallAnalyticsStreamTranscriptionRequest.add_member(:language_model_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ModelName, location_name: 'LanguageModelName', traits: {"smithy.api#documentation" => "<p>Specify the name of the custom language model that you want to use when processing your\n      transcription. Note that language model names are case sensitive.</p>\n         <p>The language of the specified language model must match the language code you specify\n      in your transcription request. If the languages don't match, the custom language model isn't applied. \n      There are no errors or warnings associated with a language mismatch.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/custom-language-models.html\">Custom language models</a>.</p>", "smithy.api#httpHeader" => "x-amzn-transcribe-language-model-name"}))
    StartCallAnalyticsStreamTranscriptionRequest.add_member(:enable_partial_results_stabilization, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EnablePartialResultsStabilization', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Enables partial result stabilization for your transcription. Partial result stabilization can reduce\n      latency in your output, but may impact accuracy. For more information, see \n      <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/streaming.html#streaming-partial-result-stabilization\">Partial-result \n        stabilization</a>.</p>", "smithy.api#httpHeader" => "x-amzn-transcribe-enable-partial-results-stabilization"}))
    StartCallAnalyticsStreamTranscriptionRequest.add_member(:partial_results_stability, Smithy::Schema::Shapes::ShapeRef.new(shape: PartialResultsStability, location_name: 'PartialResultsStability', traits: {"smithy.api#documentation" => "<p>Specify the level of stability to use when you enable partial results stabilization \n      (<code>EnablePartialResultsStabilization</code>).</p>\n         <p>Low stability provides the highest accuracy. High stability transcribes faster, but with slightly\n      lower accuracy.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/streaming.html#streaming-partial-result-stabilization\">Partial-result \n      stabilization</a>.</p>", "smithy.api#httpHeader" => "x-amzn-transcribe-partial-results-stability"}))
    StartCallAnalyticsStreamTranscriptionRequest.add_member(:content_identification_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ContentIdentificationType, location_name: 'ContentIdentificationType', traits: {"smithy.api#documentation" => "<p>Labels all personally identifiable information (PII) identified in your transcript.</p>\n         <p>Content identification is performed at the segment level; PII specified in \n      <code>PiiEntityTypes</code> is flagged upon complete transcription of an audio segment. If you don't\n      include <code>PiiEntityTypes</code> in your request, all PII is identified.</p>\n         <p>You can’t set <code>ContentIdentificationType</code> and <code>ContentRedactionType</code>\n      in the same request. If you set both, your request returns a\n      <code>BadRequestException</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/pii-redaction.html\">Redacting or identifying personally identifiable\n      information</a>.</p>", "smithy.api#httpHeader" => "x-amzn-transcribe-content-identification-type"}))
    StartCallAnalyticsStreamTranscriptionRequest.add_member(:content_redaction_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ContentRedactionType, location_name: 'ContentRedactionType', traits: {"smithy.api#documentation" => "<p>Redacts all personally identifiable information (PII) identified in your transcript.</p>\n         <p>Content redaction is performed at the segment level; PII specified in \n      <code>PiiEntityTypes</code> is redacted upon complete transcription of an audio segment. If you don't\n      include <code>PiiEntityTypes</code> in your request, all PII is redacted.</p>\n         <p>You can’t set <code>ContentRedactionType</code> and <code>ContentIdentificationType</code>\n      in the same request. If you set both, your request returns a <code>BadRequestException</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/pii-redaction.html\">Redacting or identifying personally identifiable\n      information</a>.</p>", "smithy.api#httpHeader" => "x-amzn-transcribe-content-redaction-type"}))
    StartCallAnalyticsStreamTranscriptionRequest.add_member(:pii_entity_types, Smithy::Schema::Shapes::ShapeRef.new(shape: PiiEntityTypes, location_name: 'PiiEntityTypes', traits: {"smithy.api#documentation" => "<p>Specify which types of personally identifiable information (PII) you want to redact in your \n      transcript. You can include as many types as you'd like, or you can select \n      <code>ALL</code>.</p>\n         <p>Values must be comma-separated and can include: <code>ADDRESS</code>, \n      <code>BANK_ACCOUNT_NUMBER</code>, <code>BANK_ROUTING</code>,\n      <code>CREDIT_DEBIT_CVV</code>, <code>CREDIT_DEBIT_EXPIRY</code>,\n      <code>CREDIT_DEBIT_NUMBER</code>, <code>EMAIL</code>, \n      <code>NAME</code>, <code>PHONE</code>, <code>PIN</code>, \n      <code>SSN</code>, or <code>ALL</code>.</p>\n         <p>Note that if you include <code>PiiEntityTypes</code> in your request, you must also include \n      <code>ContentIdentificationType</code> or <code>ContentRedactionType</code>.</p>\n         <p>If you include <code>ContentRedactionType</code> or \n      <code>ContentIdentificationType</code> in your request, but do not include \n      <code>PiiEntityTypes</code>, all PII is redacted or identified.</p>", "smithy.api#httpHeader" => "x-amzn-transcribe-pii-entity-types"}))
