    StartStreamTranscriptionRequest.add_member(:number_of_channels, Smithy::Schema::Shapes::ShapeRef.new(shape: NumberOfChannels, location_name: 'NumberOfChannels', traits: {"smithy.api#documentation" => "<p>Specify the number of channels in your audio stream. This value must be \n      <code>2</code>, as only two channels are supported. If your audio doesn't contain \n      multiple channels, do not include this parameter in your request.</p>\n         <p>If you include <code>NumberOfChannels</code> in your request, you must also \n      include <code>EnableChannelIdentification</code>.</p>", "smithy.api#httpHeader" => "x-amzn-transcribe-number-of-channels"}))
